-- SP-03 canonical supplier evaluation/disputes and source-owned holds.
CREATE TABLE "sm_supplier_holds" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"source_type" TEXT NOT NULL,"source_id" TEXT NOT NULL,"reason" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"base_status" TEXT NOT NULL,"created_by" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL,"released_by" TEXT,"released_at" TIMESTAMP(3),"release_reason" TEXT,CONSTRAINT "sm_supplier_holds_pkey" PRIMARY KEY ("id"),CONSTRAINT "sm_supplier_holds_base_status_check" CHECK ("base_status" IN ('ACTIVE','INACTIVE')));
CREATE UNIQUE INDEX "sm_supplier_holds_company_id_source_type_source_id_key" ON "sm_supplier_holds"("company_id","source_type","source_id");
CREATE INDEX "sm_supplier_holds_company_id_supplier_id_active_idx" ON "sm_supplier_holds"("company_id","supplier_id","active");
CREATE INDEX "sm_supplier_holds_company_id_supplier_id_source_type_active_idx" ON "sm_supplier_holds"("company_id","supplier_id","source_type","active");
ALTER TABLE "sm_supplier_holds" ADD CONSTRAINT "sm_supplier_holds_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "sm_supplier_holds" ("id","company_id","supplier_id","source_type","source_id","reason","active","base_status","created_by","created_at") SELECT 'legacy-manual-hold:'||"company_id"||':'||"id","company_id","id",'LEGACY_MANUAL_HOLD','legacy:'||"id",'Existing ON_HOLD supplier preserved during SP-03 migration',true,'ACTIVE','SYSTEM_MIGRATION',CURRENT_TIMESTAMP FROM "sm_supplier_profiles" WHERE "status"='ON_HOLD' ON CONFLICT ("company_id","source_type","source_id") DO NOTHING;
CREATE TABLE "se_supplier_evaluations" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"branch_id" TEXT NOT NULL,"supplier_party_id" TEXT NOT NULL,"version" INTEGER NOT NULL,"quality_score" INTEGER NOT NULL,"service_score" INTEGER NOT NULL,"notes" TEXT,"evaluated_by" TEXT NOT NULL,"evaluated_at" TIMESTAMP(3) NOT NULL,"request_id" TEXT NOT NULL,"request_hash" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "se_supplier_evaluations_pkey" PRIMARY KEY ("id"),CONSTRAINT "se_supplier_evaluations_quality_score_check" CHECK ("quality_score" BETWEEN 1 AND 5),CONSTRAINT "se_supplier_evaluations_service_score_check" CHECK ("service_score" BETWEEN 1 AND 5));
CREATE UNIQUE INDEX "se_supplier_evaluations_company_branch_supplier_version_key" ON "se_supplier_evaluations"("company_id","branch_id","supplier_party_id","version");
CREATE UNIQUE INDEX "se_supplier_evaluations_company_branch_request_key" ON "se_supplier_evaluations"("company_id","branch_id","request_id");
CREATE INDEX "se_supplier_evaluations_company_branch_supplier_evaluated_idx" ON "se_supplier_evaluations"("company_id","branch_id","supplier_party_id","evaluated_at");
CREATE TABLE "sd_supplier_disputes" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"branch_id" TEXT NOT NULL,"supplier_party_id" TEXT NOT NULL,"severity" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"attachment_ids" JSONB NOT NULL,"opened_by" TEXT NOT NULL,"opened_at" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"request_id" TEXT NOT NULL,"request_hash" TEXT NOT NULL,"resolved_by" TEXT,"resolved_at" TIMESTAMP(3),"resolution" TEXT,"cancelled_by" TEXT,"cancelled_at" TIMESTAMP(3),"cancellation_reason" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "sd_supplier_disputes_pkey" PRIMARY KEY ("id"),CONSTRAINT "sd_supplier_disputes_severity_check" CHECK ("severity" IN ('LOW','MEDIUM','HIGH','CRITICAL')),CONSTRAINT "sd_supplier_disputes_status_check" CHECK ("status" IN ('OPEN','RESOLVED','CANCELLED')),CONSTRAINT "sd_supplier_disputes_title_check" CHECK (length(btrim("title"))>0),CONSTRAINT "sd_supplier_disputes_description_check" CHECK (length(btrim("description"))>0));
CREATE UNIQUE INDEX "sd_supplier_disputes_company_branch_id_key" ON "sd_supplier_disputes"("company_id","branch_id","id");
CREATE UNIQUE INDEX "sd_supplier_disputes_company_branch_request_key" ON "sd_supplier_disputes"("company_id","branch_id","request_id");
CREATE INDEX "sd_supplier_disputes_company_branch_supplier_opened_idx" ON "sd_supplier_disputes"("company_id","branch_id","supplier_party_id","opened_at");
CREATE INDEX "sd_supplier_disputes_company_branch_supplier_status_idx" ON "sd_supplier_disputes"("company_id","branch_id","supplier_party_id","status");
CREATE TABLE "sd_supplier_dispute_history" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"branch_id" TEXT NOT NULL,"dispute_id" TEXT NOT NULL,"action" TEXT NOT NULL,"actor_id" TEXT NOT NULL,"acted_at" TIMESTAMP(3) NOT NULL,"metadata" JSONB NOT NULL,"idempotency_key" TEXT NOT NULL,CONSTRAINT "sd_supplier_dispute_history_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sd_supplier_dispute_history_company_branch_dispute_idempotency_key" ON "sd_supplier_dispute_history"("company_id","branch_id","dispute_id","idempotency_key");
CREATE INDEX "sd_supplier_dispute_history_company_branch_dispute_acted_idx" ON "sd_supplier_dispute_history"("company_id","branch_id","dispute_id","acted_at");
ALTER TABLE "sd_supplier_dispute_history" ADD CONSTRAINT "sd_supplier_dispute_history_dispute_fkey" FOREIGN KEY ("company_id","branch_id","dispute_id") REFERENCES "sd_supplier_disputes"("company_id","branch_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
